function surfaceHud(){if(!surfaceActive)return;const x=surfaceState,a=LS.actor(x),nav=LS.navigation(x),context=LS.context(x);$('surfaceModeLabel').textContent=x.mode==='walk'?'ON FOOT':'ROVER';$('surfaceOxygen').value=x.oxygen;$('surfaceBattery').value=x.battery;$('surfaceOxygenText').textContent=Math.ceil(x.oxygen)+'%';$('surfaceBatteryText').textContent=Math.ceil(x.battery)+'%';$('surfaceDestination').textContent=x.samples.length===4&&!x.flag?'Plant your flag':nav.label;$('surfaceDistance').textContent=Math.round(nav.distance)+' m';$('surfaceBearing').style.transform='rotate('+(-nav.bearing)+'rad)';$('surfaceHomeDistance').textContent=Math.round(Math.hypot(a.x,a.z))+' m';
 for(const b of document.querySelectorAll('[data-surface-sample]')){const id=b.dataset.surfaceSample,done=x.samples.includes(id);b.classList.toggle('collected',done);b.disabled=done;b.textContent=done?'✓':id;b.setAttribute('aria-pressed',String(x.waypoint===id&&!done));b.setAttribute('aria-label',done?'Sample '+id+' collected':'Navigate to sample '+id);}
 $('surfaceFlagStatus').classList.toggle('planted',!!x.flag);$('surfaceFlagStatus').setAttribute('aria-label',x.flag?'Flag planted':'Flag not yet planted');$('surfaceMessage').textContent=x.message;$('surfaceInteract').textContent=context.label;$('surfaceInteract').disabled=!context.enabled||x.paused||!!x.event;$('surfaceVehicle').textContent=x.mode==='walk'?'🛞':'🚶';$('surfaceVehicle').setAttribute('aria-label',x.mode==='walk'?'Enter rover':'Leave rover');$('surfaceVehicle').disabled=x.paused||!!x.event||x.phase!=='active'||(x.mode==='walk'?Math.hypot(x.walker.x-x.rover.x,x.walker.z-x.rover.z)>5:Math.abs(x.rover.speed)>1.5);$('surfaceJump').disabled=x.mode!=='walk'||x.paused||x.phase!=='active'||!!x.event;$('surfaceFlag').disabled=!!x.flag||x.mode!=='walk'||x.paused||x.phase!=='active'||!!x.event;$('surfacePause').textContent=x.paused?'▶':'Ⅱ';$('surfacePause').setAttribute('aria-label',x.paused?'Resume exploration':'Pause exploration');$('surfacePaused').hidden=!x.paused||x.phase!=='active'||!!x.event;$('surfaceSound').textContent=sound.settings.muted?'🔇':'🔊';
 const overlay=!!x.event||x.phase==='complete'||x.phase==='rescue';$('surfaceOverlay').hidden=!overlay;$('surfaceEventChoices').hidden=!x.event;$('surfaceRescue').hidden=x.phase!=='rescue';$('surfaceFinish').hidden=x.phase!=='complete';$('surfaceRestart').hidden=x.phase!=='complete';if(x.event){$('surfaceOverlayIcon').textContent='🛠';$('surfaceOverlayTitle').textContent=x.event.title;$('surfaceOverlayText').textContent=x.event.text;}else if(x.phase==='complete'){$('surfaceOverlayIcon').textContent='🏆';$('surfaceOverlayTitle').textContent='Moon survey complete!';$('surfaceOverlayText').textContent='4 samples secured · Flag planted · Crew back at the ship';}else if(x.phase==='rescue'){$('surfaceOverlayIcon').textContent='🚀';$('surfaceOverlayTitle').textContent='Rescue pickup ready';$('surfaceOverlayText').textContent='Return safely to the ship. Your collected samples will stay with you.';}surfaceView?.minimap($('surfaceMap'));
}
function surfaceInput(){const on=key=>surfaceKeys.has(key)||[...surfaceTouches.values()].includes(key),jump=surfaceJump;surfaceJump=false;return {forward:(on('forward')?1:0)-(on('back')?1:0),turn:(on('left')?1:0)-(on('right')?1:0),jump};}
function surfaceUpdate(elapsed,ms){const before=surfaceState.phase;LS.advance(surfaceState,surfaceInput(),elapsed);if(surfaceState.mode==='walk'&&surfaceState.walker.distance-lastSurfaceStep>.75){lastSurfaceStep=surfaceState.walker.distance;sound.cue('step');}if(surfaceState.event&&!lastSurfaceEvent){sound.cue('alert');surfaceClearInput();surfaceSave();}lastSurfaceEvent=surfaceState.event;if(surfaceState.phase!==before){surfaceClearInput();surfaceSave();}surfaceCompleted();if(ms>=nextSurfaceSave){surfaceSave();nextSurfaceSave=ms+5000;}}
const surfaceKeyMap={KeyW:'forward',ArrowUp:'forward',KeyS:'back',ArrowDown:'back',KeyA:'left',ArrowLeft:'left',KeyD:'right',ArrowRight:'right'};
function surfaceKeyDown(e){if(!surfaceActive||$('surfaceHelpDialog').open)return;if(surfaceKeyMap[e.code]){e.preventDefault();surfaceKeys.add(surfaceKeyMap[e.code]);}if(e.code==='Space'&&e.target.tagName!=='BUTTON'){e.preventDefault();if(!e.repeat)surfaceJump=true;}if(!e.repeat){if(e.code==='KeyE'){e.preventDefault();surfaceInteract();}if(e.code==='KeyP'){e.preventDefault();surfacePause();}if(e.code==='KeyF')$('surfaceFlag').click();if(e.code==='KeyR')$('surfaceVehicle').click();}}
$('exploreMoon').onclick=()=>surfaceBegin();$('resumeSurface').onclick=()=>{if(!surfaceSaved)return;$('settingsDialog').close();surfaceBegin(LS.restore(LS.serialize(surfaceSaved)));};$('surfaceClose').onclick=surfaceClose;$('surfaceFinish').onclick=surfaceClose;$('surfacePause').onclick=()=>surfacePause();$('surfaceInteract').onclick=surfaceInteract;$('surfaceVehicle').onclick=()=>{if(LS.toggleVehicle(surfaceState)){sound.cue('deploy');surfaceSave();}surfaceHud();};$('surfaceFlag').onclick=()=>{if(LS.plantFlag(surfaceState)){sound.cue('flag');surfaceSave();}surfaceHud();};$('surfaceJump').onclick=()=>{surfaceJump=true;};$('surfaceHome').onclick=()=>{surfaceState.waypoint='home';surfaceHud();};
$('surfaceSound').onclick=()=>{sound.configure({muted:!sound.settings.muted});sound.unlock();surfaceHud();};for(const b of document.querySelectorAll('[data-surface-sample]'))b.onclick=()=>{surfaceState.waypoint=b.dataset.surfaceSample;surfaceHud();};
for(const b of document.querySelectorAll('[data-surface-control]')){b.onpointerdown=e=>{if(!surfaceActive||surfaceState.paused||surfaceState.event)return;e.preventDefault();b.setPointerCapture(e.pointerId);surfaceTouches.set(e.pointerId,b.dataset.surfaceControl);b.classList.add('held');};for(const event of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(event,e=>{surfaceTouches.delete(e.pointerId);b.classList.remove('held');});}
for(const b of document.querySelectorAll('[data-surface-response]'))b.onclick=()=>{if(LS.respond(surfaceState,b.dataset.surfaceResponse)){sound.cue('deploy');surfaceSave();surfaceHud();}};$('surfaceRescue').onclick=()=>{LS.rescue(surfaceState);surfaceClearInput();surfaceView.initialCamera=true;surfaceSave();surfaceHud();};$('surfaceRestart').onclick=()=>{if(!confirm('Start a fresh Moon survey?'))return;surfaceState=LS.create(surfaceState.meta,surfaceState.seed);surfaceView.dispose();surfaceView=new SurfaceView(renderer,surfaceState,{ship:s.phase==='landed'&&s.body==='Moon'?rocket:null,earthTexture:surfaceTexture,earthDirection:surfaceState.meta.earthDirection});surfaceClearInput();surfaceSave();surfaceHud();};
$('surfaceHelp').onclick=()=>{surfaceHelpResume=!surfaceState.paused;surfacePause(true);$('surfaceHelpDialog').showModal();};$('surfaceHelpClose').onclick=()=>$('surfaceHelpDialog').close();$('surfaceHelpDialog').addEventListener('close',()=>{if(surfaceActive&&surfaceHelpResume)surfacePause(false);});
