const editHistory=[];
function remember(){editHistory.push(JSON.stringify(design));if(editHistory.length>40)editHistory.shift();}
function edited(){sound.cue('build');design=P.design(design);zoom=1;panX=panY=0;renderEditor();updatePreview();$('buildHint').style.opacity='0';}
function updatePalette(){
 const locked=s.phase!=='ready',st=design.stages[selectedStage];
 $('selectStage1').setAttribute('aria-pressed',String(selectedStage===0));$('selectStage2').setAttribute('aria-pressed',String(selectedStage===1));
 $('partCount').textContent=st.tanks+' ⛽ · '+st.engines+' 🔥';
 for(const b of document.querySelectorAll('[data-add]')){const item=OrbitalParts.find(p=>p.id===b.dataset.add),target=item.stage?design.stages[0]:design;const active=item.toggle&&!!target[item.id];b.setAttribute('aria-pressed',String(active));b.classList.toggle('chosen',active);b.disabled=locked||(item.key==='tanks'&&st.tanks>=6)||(item.key==='engines'&&st.engines>=3)||(item.id==='boosters'&&design.stages[0].boosters>=2);}
 $('removeTank').disabled=locked||!st.tanks;$('removeEngine').disabled=locked||!st.engines;$('undoEdit').disabled=locked||!editHistory.length;$('clearDesign').disabled=locked;
 $('selectStage1').disabled=locked;$('selectStage2').disabled=locked;
}
function addPart(id){if(s.phase!=='ready')return;const item=OrbitalParts.find(p=>p.id===id);if(!item)return;const st=design.stages[selectedStage];if(item.key==='tanks'&&st.tanks>=6||item.key==='engines'&&st.engines>=3||id==='boosters'&&design.stages[0].boosters>=2)return;remember();if(id==='payload'){const values=[800,1500,2500];design.payload=values[(values.indexOf(design.payload)+1)%values.length];}else if(item.toggle){const target=item.stage?design.stages[0]:design;target[id]=!target[id];}else if(item.key==='tanks'){st.tankSizes.push(item.size);st.tanks++;}else if(item.key==='engines'){st.engineType=item.engine;st.engines++;}else if(id==='boosters')design.stages[0].boosters++;edited();$('quickStatus').textContent=item.label;}
let category='';for(const item of OrbitalParts){if(item.group!==category){category=item.group;const heading=document.createElement('div');heading.className='palette-title';heading.textContent=category;$('partsCatalog').append(heading);}const b=document.createElement('button');b.className='part-tile';b.dataset.add=item.id;b.draggable=true;b.title=item.tip;b.setAttribute('aria-label',item.label+'. '+item.tip);const art=document.createElement('span');art.className='part-art '+item.art;const label=document.createElement('span');label.textContent=item.label;b.append(art,label);b.onclick=()=>addPart(item.id);b.ondragstart=e=>{if(s.phase!=='ready'){e.preventDefault();return;}e.dataTransfer.setData('application/x-rocket-part',item.id);e.dataTransfer.effectAllowed='copy';};$('partsCatalog').append(b);}
$('viewport').ondragover=e=>{if(s.phase==='ready')e.preventDefault();};$('viewport').ondrop=e=>{e.preventDefault();const key=e.dataTransfer.getData('application/x-rocket-part');if(key)addPart(key);};
for(const i of [0,1])$('selectStage'+(i+1)).onclick=()=>{selectedStage=i;updatePalette();hud();};
for(const [id,key]of [['removeTank','tanks'],['removeEngine','engines']])$(id).onclick=()=>{if(s.phase!=='ready'||!design.stages[selectedStage][key])return;remember();design.stages[selectedStage][key]--;if(key==='tanks')design.stages[selectedStage].tankSizes.pop();edited();};
$('undoEdit').onclick=()=>{if(s.phase!=='ready'||!editHistory.length)return;design=P.design(JSON.parse(editHistory.pop()));edited();};
$('clearDesign').onclick=()=>{if(s.phase!=='ready'||!confirm('Clear the rocket parts? You can undo this.'))return;remember();design.stages.forEach(st=>{st.tanks=0;st.engines=0;st.tankSizes=[];st.boosters=0;st.radialSeparator=false;});for(const key in P.ATTACHMENTS)design[key]=false;design.separator=false;edited();};
$('centerView').onclick=()=>{zoom=1;panX=panY=0;cameraAngle=.45;cameraTilt=-.08;if(s.phase!=='ready'&&flightCamera==='ground'){fixedCenter=P.add(s.p,P.mul(launchAnchor,-1));fixedHalf=100;fixedManual=true;}draw();};
$('zoomIn').onclick=()=>zoom=P.clamp(zoom*.8,.3,6);$('zoomOut').onclick=()=>zoom=P.clamp(zoom*1.25,.3,6);
function openDialog(id){const d=$(id);if(d.open)return;d.dataset.resume=String(s.phase==='flying'&&!paused);if(d.dataset.resume==='true')pause();d.showModal();if(id==='settingsDialog')$('menuBtn').setAttribute('aria-expanded','true');}
$('menuBtn').onclick=()=>openDialog('settingsDialog');$('helpBtn').onclick=()=>openDialog('helpDialog');$('systemsBtn').onclick=()=>openDialog('systemsDialog');
for(const b of document.querySelectorAll('[data-close]'))b.onclick=()=>$(b.dataset.close).close();
for(const id of ['settingsDialog','helpDialog','systemsDialog'])$(id).addEventListener('close',()=>{$('menuBtn').setAttribute('aria-expanded','false');if($(id).dataset.resume==='true'&&s.phase==='flying'&&paused)pause();});
$('saveQuick').onclick=()=>{$('saveDesign').click();$('quickStatus').textContent='Saved ✓';};$('loadQuick').onclick=()=>{$('loadDesign').click();$('quickStatus').textContent=savedDesign?'Loaded ✓':'Save a rocket first';};
function updatePreview(){if(s.phase==='flying')return;s=createFlight();localSurface=P.mul(P.unit(s.p),P.BODIES[s.body].radius);if(rendererReady){buildRocket();buildPlanet();}trailPoints=[];predPoints=[];predictionTime=-100;hud();}
function renderEditor(){
 $('craftName').value=design.name;$('payload').value=design.payload;
 $('stages').replaceChildren();design.stages.forEach((st,i)=>{const box=document.createElement('div');box.className='stage-card';const heading=document.createElement('h3');heading.textContent=i===0?'STAGE 1 / BOOSTER':'STAGE 2 / UPPER STAGE';box.append(heading);for(const [key,label,max]of [['tanks','Fuel tanks',6],['engines','Engines',3]]){const row=document.createElement('div');row.className='stepper';const text=document.createElement('span');text.textContent=label;const buttons=document.createElement('div');const count=document.createElement('b');count.textContent=st[key];for(const delta of [-1,1]){const b=document.createElement('button');b.textContent=delta===1?'+':'−';b.setAttribute('aria-label',(delta===1?'Add ':'Remove ')+label.toLowerCase()+' stage '+(i+1));b.dataset.edit='true';b.disabled=s.phase!=='ready'||(delta===1?st[key]>=max:st[key]<=0);b.onclick=()=>{remember();design.stages[i][key]=P.clamp(st[key]+delta,0,max);edited();};buttons.append(b);if(delta===-1)buttons.append(count);}row.append(text,buttons);box.append(row);} $('stages').append(box);});
 const stats=P.specs(design),issues=P.validate(design,['moon','moon-orbit'].includes(scenario)?'Moon':'Earth');$('buildMass').textContent=(stats.mass/1000).toFixed(1)+' t';$('buildTwr').textContent=stats.twr.toFixed(2);$('buildThrust').textContent=Math.round(stats.stages[0].thrust/1000)+' kN';$('buildDv').textContent=Math.round(stats.deltaV)+' m/s';$('readiness').textContent=issues.length?(issues.some(x=>x.includes('side release'))?'⚠ Fit side releases for boosters.':issues.some(x=>x.includes('needs'))?'⚠ Each stage needs tanks + engines.':'⚠ More engines or less weight.') :'';$('launch').disabled=!rendererReady||issues.length>0||s.phase!=='ready';
 if(scenario==='expedition'&&!issues.length&&stats.deltaV<7400)$('readiness').textContent='🚀 Use Moon Explorer for the full journey.';updatePalette();$('scenarioHelp').textContent=scenario==='expedition'?'Continuous Earth–Moon journey. Use Moon Explorer from settings, launch, then Reach orbit, Travel and Land. Date-based Astronomy Engine positions; all lengths are scaled 1:10 with consistent model time.':scenario==='moon'?'Practice descent under lunar gravity. This is a separate starting scenario.':scenario==='moon-orbit'?'Start in a circular orbit 30 km above the Moon. Burn forward to raise your orbit; backward to lower it.':scenario==='orbit'?'Start in a circular Earth orbit. Practise prograde and retrograde burns.':'Launch from rest. Reach a stable orbit above the 70 km atmosphere.';
}
function setEditorLocked(locked){document.body.classList.toggle('flying',locked);for(const id of ['craftName','payload','scenario','saveDesign','loadDesign','defaultDesign','expeditionRocket','missionDate','missionMode'])$(id).disabled=locked;renderEditor();}
$('craftName').onchange=()=>{design.name=$('craftName').value.trim()||'Pioneer';};$('payload').onchange=()=>{remember();design.payload=Number($('payload').value);edited();};$('scenario').onchange=()=>{scenario=$('scenario').value;renderEditor();updatePreview();};
$('saveDesign').onclick=()=>{design.name=$('craftName').value.trim()||'Pioneer';savedDesign=P.design(design);writeSave('Design saved on this browser.');};$('loadDesign').onclick=()=>{if(!savedDesign){$('saveStatus').textContent='No saved design yet. Save a design first.';return;}remember();design=P.design(savedDesign);edited();$('saveStatus').textContent='Saved design loaded.';};$('defaultDesign').onclick=()=>{remember();design=P.design(P.DEFAULT);edited();};
function clearInput(){held.clear();touches.clear();document.querySelectorAll('[data-control]').forEach(b=>b.classList.remove('held'));}
function setThrottle(value){s.throttle=P.clamp(value,0,1);$('throttle').value=Math.round(s.throttle*100);$('throttleValue').textContent=Math.round(s.throttle*100)+'%';}
$('throttle').oninput=()=>{takeManual();setThrottle(Number($('throttle').value)/100);};$('cutoff').onclick=()=>{takeManual();setThrottle(0);};
function status(text){$('flightStatus').textContent=text;}
function start(){if(P.validate(design,['moon','moon-orbit'].includes(scenario)?'Moon':'Earth').length||!rendererReady)return;sound.stop();sound.setBlocked(false);sound.unlock();sound.cue('launch');clearDebris();s=createFlight();localSurface=P.mul(P.unit(s.p),P.BODIES[s.body].radius);launchAnchor=P.mul(P.unit(s.p),P.BODIES[s.body].radius);flightCamera=['launch','moon','expedition'].includes(scenario)?'ground':'follow';fixedHalf=scenario==='moon'?800:50;fixedCenter=scenario==='moon'?[0,600,0]:[0,30,0];fixedManual=false;mapScope='local';$('mapFocus').value='local';mapFocusCraft=false;s.phase='flying';paused=false;terminal=false;requestedWarp=warp=1;map=false;zoom=1;trailPoints=[];predPoints=[];predictionTime=-100;last=0;nextDraw=0;nextHud=0;acc=0;clearInput();setThrottle(0);$('attitude').value=scenario==='launch'?'guide':'manual';$('result').hidden=true;buildPlanet();buildRocket();setEditorLocked(true);document.body.dataset.graphics='flight';$('cameraMode').textContent=flightCamera==='ground'?'Fixed ▣':'Follow 🚀';$('pause').textContent='Ⅱ';$('timewarp').textContent='×1';$('viewMode').textContent='Map ◎';status(scenario==='launch'?'🔥 Turn up the slider!':'🔥 Use the slider to fly.');$('scene').focus({preventScroll:true});hud();}
$('launch').onclick=start;
function reset(){if(surfaceActive)surfaceClose();sound.stop();clearDebris();records.maxAltitude=Math.max(Number(records.maxAltitude)||0,s.maxAltitude);writeSave();s.phase='ready';paused=false;terminal=false;map=false;preview3d=false;document.body.dataset.graphics='blueprint';$('cameraMode').textContent='3D ↻';$('viewMode').textContent='Map ◎';clearInput();setThrottle(0);$('result').hidden=true;setEditorLocked(false);updatePreview();$('pause').textContent='Ⅱ';requestedWarp=warp=1;$('timewarp').textContent='×1';status('☝ Tap parts to build.');}
function restart(){if(s.phase==='flying'&&!confirm('Leave this flight and return to assembly? Your design stays; the active flight is discarded.'))return;reset();}
$('restart').onclick=restart;$('resultRetry').onclick=reset;
function pause(){if(s.phase!=='flying')return;paused=!paused;sound.setBlocked(paused||document.hidden);clearInput();last=0;acc=0;$('pause').textContent=paused?'▶':'Ⅱ';$('pause').setAttribute('aria-label',paused?'Resume flight':'Pause flight');status(paused?'Flight paused. Fuel and simulation time are frozen.':'Flight resumed.');hud();}
