$('viewMode').onclick=()=>{map=!map;mapScope='local';$('mapFocus').value='local';mapFocusCraft=false;$('viewMode').textContent=map?'Fly 🚀':'Map ◎';zoom=1;hud();draw();};$('solarView').onclick=()=>{map=true;mapScope='solar';solarFocus='Sun';$('mapFocus').value='solar';$('solarTarget').value='Sun';$('viewMode').textContent='Fly 🚀';mapFocusCraft=false;zoom=1;hud();draw();};$('cameraMode').onclick=()=>{if(s.phase==='ready'){preview3d=!preview3d;zoom=1;$('cameraMode').textContent=preview3d?'Grid ▦':'3D ↻';document.body.dataset.graphics=preview3d?'preview':'blueprint';}else{flightCamera=flightCamera==='ground'?'follow':flightCamera==='follow'?'free':'ground';orbitCamera=flightCamera==='free';if(flightCamera==='ground'){fixedCenter=P.add(s.p,P.mul(launchAnchor,-1));fixedHalf=80;fixedManual=true;}$('cameraMode').textContent=flightCamera==='ground'?'Fixed ▣':flightCamera==='follow'?'Follow 🚀':'Free ↻';zoom=1;}draw();};
