const keyMap={KeyW:'pitchDown',ArrowUp:'pitchDown',KeyS:'pitchUp',ArrowDown:'pitchUp',KeyA:'yawLeft',ArrowLeft:'yawLeft',KeyD:'yawRight',ArrowRight:'yawRight'};
